class Solution {
public:
    ListNode* mergeInBetween(ListNode* list1, int a, int b, ListNode* list2) {
        ListNode *prev = nullptr, *after = list1;
        for (int i = 0; i < a; ++i) {
            prev = after;
            after = after->next;
        }
        for (int i = a; i <= b; ++i)
            after = after->next;

        ListNode* tail = list2;
        while (tail->next) tail = tail->next;

        prev->next = list2;
        tail->next = after;
        return list1;
    }
};
